import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"编译器通行证","description":"","frontmatter":{"title":"编译器通行证","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compiler-passes.md","filePath":"cs/compiler-passes.md","lastUpdated":1789023840000}'),h={name:"cs/compiler-passes.md"};function E(A,a,m,B,_,f){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="编译器通行证" tabindex="-1">编译器通行证 <a class="header-anchor" href="#编译器通行证" aria-label="Permalink to &quot;编译器通行证&quot;">​</a></h1><div class="epigraph"><p>源程序是字符串；要变成可链接的机器码，必须分成可独立陈述的几遍：词法、语法、语义、中间代码、后端。</p><footer>—— 据 Aho, Lam, Sethi and Ullman, Compilers: Principles, Techniques, and Tools 整理</footer></div><p>上一课<a href="/cs/randomized-algo">随机化算法直觉</a>把算法课收到期望时间与蒙特卡洛对照；<a href="/cs/npc-canonical">NPC 典型问题</a>已经能分类。本课不重写归约。缺口是：源文本<strong>还不是图</strong>，也还不是邻接表上的过程——它是字符序列。要把「当算法分析」变成「当程序执行」，必须先有一层层的结构。本课是程序语言与编译课程的第一课；后课默认已经读完本课的通行证划分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>算法课的输入是数组、图、串模式。编译器的输入是源文件。没有词法，没有记号；没有语法，没有短语结构；没有类型，没有可翻译的运算。若把整份字符串当一个 NPC 实例来「优化」，既无对象也无多项式保证。缺口是<strong>通行证</strong>：每一遍的输入输出类型固定，后面的课一次只补一层。</p><p>前端：字符 \\(\\to\\) 记号 \\(\\to\\) 语法树 \\(\\to\\) 带类型的抽象语法。中端：中间表示与分析。后端：指令、寄存器、目标文件。<a href="/cs/calling-convention-stack">调用约定</a>与<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>已在组成课；本课不重讲 ISA，只声明后端会用到它们。</p><h3 id="一遍不是「再扫一次文件」的别名" tabindex="-1">一遍不是「再扫一次文件」的别名 <a class="header-anchor" href="#一遍不是「再扫一次文件」的别名" aria-label="Permalink to &quot;一遍不是「再扫一次文件」的别名&quot;">​</a></h3><p>逻辑遍可以合并实现，但接口不能混：词法不负责括号匹配，语法不负责「未声明变量」，IR 不负责选具体 opcode。龙书的 front/middle/back 是本课程的地图。</p><p><span class="marginnote">Aho, Lam, Sethi, Ullman（龙书）把编译写成分析与综合。本课地图只列主干遍；链接与运行时在课程末尾才接操作系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规定管道。错误在哪一遍报告，就在那一层的语言里陈述。中间表示隔离前端语言与后端 ISA，使优化不绑死某一指令集。</p>',11)),(e(),n(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%5B%22%E6%BA%90%E5%AD%97%E7%AC%A6%E4%B8%B2%22%5D%20--%3E%20LEX%5B%22%E8%AF%8D%E6%B3%95%22%5D%0A%20%20LEX%20--%3E%20PAR%5B%22%E8%AF%AD%E6%B3%95%22%5D%0A%20%20PAR%20--%3E%20SEM%5B%22%E8%AF%AD%E4%B9%89%20%2F%20%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20SEM%20--%3E%20IR%5B%22%E4%B8%AD%E9%97%B4%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20IR%20--%3E%20BE%5B%22%E6%8C%87%E4%BB%A4%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20BE%20--%3E%20OBJ%5B%22%E7%9B%AE%E6%A0%87%E6%96%87%E4%BB%B6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>后课按此序：正则词法、CFG、递归下降、LL、LR、AST、符号表、类型、三地址、SSA、数据流、指令选择、着色、窥孔、ABI、链接、加载、GC。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>通行证使正确性可分层验证：词法后应是合法记号流；语法后应有一棵导出自。优化必须保持可观察行为，那是中端的契约，本课只点名。多遍可以缓存 IR；JIT 把后半推迟到运行时，仍是同一管道的切片。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写正则、不写 FIRST 集、不选 x86 或 RISC-V 的具体编码。不把编译器做成 NPC 求解器：寄存器着色在一般图上困难，后课用启发式，不在第一课求解。也不进入限价簿或训练循环。</p><p>后课默认：源程序经词法到目标文件的管道已划分。下一课从字符到记号，用正则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>算法课能谈过程；源文本仍是字符串，要先分层。</li><li>编译 = 词法、语法、语义、IR、后端；链接与运行时随后。</li><li>每一课只补管道上的一层。</li><li>出处：Aho, Lam, Sethi and Ullman, <em>Compilers</em>（龙书）。</li></ul>',8))])}const P=s(h,[["render",E]]);export{S as __pageData,P as default};
